-- Guest Hub S2a (26 Nov 2026, Ahmed — DECISIONS.md 2026-11-26 «Guest Hub S2a»): a social hand-off or chat booking request
-- with no known branch alerts both branches and the first to reply takes it; the receptions may open such a conversation;
-- the bathroom amenities card and its two lab items. Generated by scripts/hub-s2a-migration.mjs — never edited once applied
-- (CLAUDE.md §12). No unit mode, licence or switch changes. No phone number in this file. Every UPDATE / DELETE has a WHERE.

-- a hand-off of «السوشيال» with no known branch goes to both branches until a staff member answers it
alter table public.hub_handoffs add column if not exists both_branches boolean not null default false;
comment on column public.hub_handoffs.both_branches is 'S2a (Ahmed, 25 Nov 2026): a hand-off of the brand unit «السوشيال» while the conversation''s branch is unknown — alerted to both branches; branch_slug holds airport-road only as a placeholder until the first staff reply sets the branch.';

-- the caller may act on this conversation: the unit's members as before (internal.can_unit), or — on «السوشيال» — a member of
-- the branch unit of the conversation's branch, or of either branch while no branch is known and it was handed to both
create or replace function internal.can_conv(c public.hub_conversations, p_level public.perm_level) returns boolean
language sql stable security definer set search_path = '' as $$
  select internal.can_unit(c.unit_id, p_level)
      or (internal.can('inbox', p_level)
          and exists (select 1 from public.hub_units b where b.id = c.unit_id and b.kind = 'brand')
          and exists (select 1 from public.hub_units u join public.hub_unit_members m on m.unit_id = u.id
                       where u.kind = 'branch' and u.status = 'active' and m.staff_id = auth.uid() and internal.can_branch(u.branch_slug)
                         and (u.branch_slug = c.branch_slug
                              or (c.branch_slug is null and exists (select 1 from public.hub_handoffs h where h.conversation_id = c.id and h.both_branches)))))
$$;
create or replace function internal.can_conv_id(p_conversation uuid, p_level public.perm_level) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select internal.can_conv(c, p_level) from public.hub_conversations c where c.id = p_conversation), false)
$$;
revoke execute on function internal.can_conv(public.hub_conversations, public.perm_level), internal.can_conv_id(uuid, public.perm_level) from public, anon;
grant execute on function internal.can_conv(public.hub_conversations, public.perm_level), internal.can_conv_id(uuid, public.perm_level) to authenticated;

drop policy if exists hub_conversations_read on public.hub_conversations;
create policy hub_conversations_read on public.hub_conversations for select to authenticated using (internal.can_conv_id(id, 'view'));
drop policy if exists hub_messages_read on public.hub_messages;
create policy hub_messages_read on public.hub_messages for select to authenticated using (internal.can_conv_id(conversation_id, 'view'));
drop policy if exists hub_conversation_events_read on public.hub_conversation_events;
create policy hub_conversation_events_read on public.hub_conversation_events for select to authenticated using (internal.can_conv_id(conversation_id, 'view'));

-- both branches' alert of one hand-off: the slots on shift of every active branch, each from its own branch number; nobody
-- on shift anywhere (or p_managers) → every branch's «مدير الاستقبال» slots; the escalation → the managers not alerted yet
create or replace function internal.hub_both_alert(p_handoff uuid, p_kind text, p_managers boolean, p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  h public.hub_handoffs;
  v_n integer := 0;
begin
  select * into h from public.hub_handoffs where id = p_handoff;
  if h.id is null then return 0; end if;
  if p_kind = 'alert' and not coalesce(p_managers, false) then
    insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
    select 'alert', h.id, s.id, internal.hub_branch_channel(s.branch_slug), 'hub_staff_alert', h.is_test from public.hub_staff_slots s
     where s.active and internal.hub_slot_covers(s, p_now) and internal.hub_branch_channel(s.branch_slug) is not null
       and s.branch_slug in (select u.branch_slug from public.hub_units u where u.kind = 'branch' and u.status = 'active')
    on conflict do nothing;
    get diagnostics v_n = row_count;
  end if;
  if v_n = 0 then
    insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
    select case when p_kind = 'alert' then 'alert' else 'escalation' end, h.id, s.id, internal.hub_branch_channel(s.branch_slug), 'hub_staff_alert', h.is_test
      from public.hub_staff_slots s
     where s.active and s.role = 'manager' and internal.hub_branch_channel(s.branch_slug) is not null
       and s.branch_slug in (select u.branch_slug from public.hub_units u where u.kind = 'branch' and u.status = 'active')
       and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.slot_id = s.id)
    on conflict do nothing;
    get diagnostics v_n = row_count;
  end if;
  return v_n;
end;
$$;
revoke execute on function internal.hub_both_alert(uuid, text, boolean, timestamptz) from public, anon, authenticated;

-- the first staff member who takes a both-branches conversation of «السوشيال» (a reply from «المحادثات» or «استلام») gives it
-- their branch; an admin or management user (every branch) leaves it unknown
create or replace function internal.hub_social_owner_before() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.branch_slug is null and new.owner_kind = 'staff' and new.owner_staff_id is not null
     and (old.owner_kind is distinct from 'staff' or old.owner_staff_id is distinct from new.owner_staff_id)
     and exists (select 1 from public.hub_units u where u.id = new.unit_id and u.kind = 'brand') then
    new.branch_slug := (select s.branch from public.staff s where s.user_id = new.owner_staff_id and s.active
                           and s.branch in (select u.branch_slug from public.hub_units u where u.kind = 'branch' and u.status = 'active'));
  end if;
  return new;
end;
$$;
drop trigger if exists hub_conversations_social_owner on public.hub_conversations;
create trigger hub_conversations_social_owner before update on public.hub_conversations for each row execute function internal.hub_social_owner_before();
-- the branch now known (the guest named it, or a staff member took it): the open both-branches hand-off becomes that branch's
create or replace function internal.hub_social_branch_after() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update public.hub_handoffs set branch_slug = new.branch_slug, both_branches = false
   where conversation_id = new.id and both_branches and closed_at is null;
  return null;
end;
$$;
drop trigger if exists hub_conversations_social_branch on public.hub_conversations;
create trigger hub_conversations_social_branch after update on public.hub_conversations for each row
  when (old.branch_slug is null and new.branch_slug is not null) execute function internal.hub_social_branch_after();
revoke execute on function internal.hub_social_owner_before(), internal.hub_social_branch_after() from public, anon, authenticated;

create or replace function internal.hub_conv_team_after() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if old.handoff_id is not null and new.handoff_id is distinct from old.handoff_id then
    update public.hub_handoffs set closed_at = coalesce(closed_at, now()) where id = old.handoff_id;
  end if;
  if new.handoff_id is not null and new.handoff_id is distinct from old.handoff_id then
    insert into public.hub_handoffs (id, conversation_id, unit_id, branch_slug, reason, is_test, both_branches)
    -- S2a (Ahmed, 25 Nov 2026): a brand unit's hand-off goes to the conversation's branch; with none known, to BOTH branches
    -- (branch_slug airport-road is a placeholder until the first staff reply) — a test account's still to the system admin only
    select new.handoff_id, new.id, new.unit_id, coalesce(u.branch_slug, new.branch_slug, 'airport-road'), new.human_reason, new.is_test,
           u.kind = 'brand' and new.branch_slug is null and not internal.hub_tester_conversation(new.id)
      from public.hub_units u where u.id = new.unit_id
    on conflict do nothing;
    perform internal.hub_handoff_queue(new.handoff_id, 'alert');
  elsif new.handoff_id is not null and new.last_staff_at is not null and new.last_staff_at is distinct from old.last_staff_at then
    update public.hub_handoffs set first_reply_at = coalesce(first_reply_at, new.last_staff_at) where id = new.handoff_id;
  end if;
  return null;
end;
$$;

create or replace function internal.hub_handoff_queue(p_handoff uuid, p_kind text, p_now timestamptz default now()) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  h public.hub_handoffs;
  v_channel uuid;
  v_n integer := 0;
begin
  select * into h from public.hub_handoffs where id = p_handoff for update;
  if h.id is null or h.closed_at is not null then return 0; end if;
  v_channel := internal.hub_branch_channel(h.branch_slug);
  -- S1c (Ahmed, 25 Nov 2026): a test account's conversation alerts only the system admin — never a reception slot
  if internal.hub_tester_conversation(h.conversation_id) then
    if p_kind = 'alert' and v_channel is not null and internal.hub_system_admin_recipient() is not null
       and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.recipient_id = internal.hub_system_admin_recipient()) then
      insert into public.hub_staff_sends (kind, handoff_id, recipient_id, channel_id, template, is_test)
      values ('alert', h.id, internal.hub_system_admin_recipient(), v_channel, 'hub_staff_alert', h.is_test);
      v_n := 1;
    end if;
    if p_kind = 'alert' then
      update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
    else
      update public.hub_handoffs set escalated_at = p_now where id = h.id;
    end if;
    return v_n;
  end if;
  -- S2a (Ahmed, 25 Nov 2026): no branch known on «السوشيال» → both branches; the first to reply takes it
  if h.both_branches then
    v_n := internal.hub_both_alert(h.id, p_kind, false, p_now);
    if p_kind = 'alert' then
      update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
    else
      update public.hub_handoffs set escalated_at = p_now where id = h.id;
    end if;
    return v_n;
  end if;
  if p_kind = 'alert' then
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and internal.hub_slot_covers(s, p_now)
      on conflict do nothing;
      get diagnostics v_n = row_count;
      if v_n = 0 then
        insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
        select 'alert', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
         where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
        on conflict do nothing;
        get diagnostics v_n = row_count;
      end if;
    end if;
    update public.hub_handoffs set alerted_at = p_now, status = case when v_n > 0 then 'alerted' else 'email_only' end where id = h.id;
  else
    if v_channel is not null then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'escalation', h.id, s.id, v_channel, 'hub_staff_alert', h.is_test from public.hub_staff_slots s
       where s.branch_slug = h.branch_slug and s.active and s.role = 'manager'
         and not exists (select 1 from public.hub_staff_sends x where x.handoff_id = h.id and x.slot_id = s.id)
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
    update public.hub_handoffs set escalated_at = p_now where id = h.id;
  end if;
  return v_n;
end;
$$;

create or replace function internal.hub_extra_alert(p_conversation uuid, p_reason text, p_summary text, p_ref text, p_managers boolean, p_reservation uuid)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  v_id uuid := gen_random_uuid();
  v_branch text;
  v_channel uuid;
  v_n integer := 0;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null then return null; end if;
  -- S2a (Ahmed, 25 Nov 2026): «السوشيال» has no branch — the conversation's; with none known, both branches
  select coalesce(u.branch_slug, c.branch_slug) into v_branch from public.hub_units u where u.id = c.unit_id;
  insert into public.hub_handoffs (id, conversation_id, unit_id, branch_slug, reason, summary, ref_text, is_test, extra, reservation_id, status, both_branches)
  values (v_id, c.id, c.unit_id, coalesce(v_branch, 'airport-road'), p_reason, left(p_summary, 120), left(p_ref, 40), c.is_test, true, p_reservation, 'pending',
          v_branch is null and not internal.hub_tester_conversation(c.id));
  if v_branch is null and not internal.hub_tester_conversation(c.id) then
    v_n := internal.hub_both_alert(v_id, 'alert', p_managers, now());
    update public.hub_handoffs set alerted_at = now(), status = case when v_n > 0 then 'alerted' else 'email_only' end where id = v_id;
    return v_id;
  end if;
  v_branch := coalesce(v_branch, 'airport-road');
  v_channel := internal.hub_branch_channel(v_branch);
  -- S1c (Ahmed, 25 Nov 2026): a test account's conversation alerts only the system admin
  if v_channel is not null and internal.hub_tester_conversation(c.id) then
    if internal.hub_system_admin_recipient() is not null then
      insert into public.hub_staff_sends (kind, handoff_id, recipient_id, channel_id, template, is_test)
      values ('alert', v_id, internal.hub_system_admin_recipient(), v_channel, 'hub_staff_alert', c.is_test);
      v_n := 1;
    end if;
  elsif v_channel is not null then
    if not coalesce(p_managers, false) then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', v_id, s.id, v_channel, 'hub_staff_alert', c.is_test from public.hub_staff_slots s
       where s.branch_slug = v_branch and s.active and internal.hub_slot_covers(s, now())
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
    if v_n = 0 then
      insert into public.hub_staff_sends (kind, handoff_id, slot_id, channel_id, template, is_test)
      select 'alert', v_id, s.id, v_channel, 'hub_staff_alert', c.is_test from public.hub_staff_slots s
       where s.branch_slug = v_branch and s.active and s.role = 'manager'
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
  end if;
  update public.hub_handoffs set alerted_at = now(), status = case when v_n > 0 then 'alerted' else 'email_only' end where id = v_id;
  return v_id;
end;
$$;

create or replace function public.hub_escalations_claim(p_now timestamptz default now(), p_limit integer default 20) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_esc integer := internal.hub_setting_int('hub_escalate_min', 30);
  r record;
  v_to text[];
  v_out jsonb := '[]'::jsonb;
begin
  for r in select c.id, c.state, c.waiting_since, u.branch_slug, c.branch_slug as conv_branch, coalesce(v.name_ar, u.name_ar) as unit_name
             from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.dining_venues v on v.id = u.dining_venue_id
            where c.state = 'human' and c.waiting_since is not null and c.escalated_at is null and not c.is_test
              and c.waiting_since <= p_now - make_interval(mins => v_esc)
            order by c.waiting_since limit least(greatest(coalesce(p_limit, 20), 1), 100)
            for update of c skip locked loop
    update public.hub_conversations set escalated_at = p_now where id = r.id;
    select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x
     where x.scope = 'branch' and x.active
       -- S2a: «السوشيال» with no known branch → both branches' recipients
       and (x.branch_slug = coalesce(r.branch_slug, r.conv_branch) or (r.branch_slug is null and r.conv_branch is null));
    -- S1c (Ahmed, 25 Nov 2026): a test account's conversation emails only the active admins
    if internal.hub_tester_conversation(r.id) then
      v_to := array(select u.email from public.staff s join auth.users u on u.id = s.user_id where s.active and s.role = 'admin' and u.email is not null order by u.email);
    elsif cardinality(v_to) = 0 then
      select coalesce(array_agg(x.email order by x.email), '{}') into v_to from public.booking_notification_recipients x where x.scope = 'central' and x.active;
    end if;
    v_out := v_out || jsonb_build_object('id', r.id, 'short', upper(left(replace(r.id::text, '-', ''), 8)), 'unit_name', r.unit_name, 'state', r.state,
                                         'waiting_min', floor(extract(epoch from p_now - r.waiting_since) / 60)::integer, 'recipients', to_jsonb(v_to));
  end loop;
  return v_out;
end;
$$;

create or replace function public.hub_staff_sends_claim(p_limit integer default 20, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  s record;
  v_out jsonb := '[]'::jsonb;
begin
  for s in select x.*, ch.address as from_address, ch.waba_id, ch.sending_enabled, coalesce(sl.phone, rr.phone) as to_phone,
                  coalesce(sl.active, rr.active, false) as target_active, h.token, h.branch_slug, h.summary, h.ref_text, h.reason, h.conversation_id,
                  h.closed_at, h.first_reply_at, h.both_branches
             from public.hub_staff_sends x
             left join public.hub_channels ch on ch.id = x.channel_id
             left join public.hub_staff_slots sl on sl.id = x.slot_id
             left join public.hub_report_recipients rr on rr.id = x.recipient_id
             left join public.hub_handoffs h on h.id = x.handoff_id
            where x.status = 'queued' and x.is_test = coalesce(p_test, false) order by x.created_at limit least(greatest(coalesce(p_limit, 20), 1), 100) for update of x skip locked loop
    -- an alert or escalation whose hand-off was answered or closed meanwhile is not sent
    if s.to_phone is null or not s.target_active or s.from_address is null
       or (s.kind in ('alert', 'escalation') and (s.closed_at is not null or s.first_reply_at is not null)) then
      update public.hub_staff_sends set status = 'skipped', error_code = case when s.from_address is null then 'no_channel' when s.to_phone is null or not s.target_active then 'no_recipient' else 'answered' end, updated_at = now()
       where id = s.id;
      continue;
    end if;
    update public.hub_staff_sends set status = 'pending', updated_at = now() where id = s.id;
    v_out := v_out || jsonb_build_object(
      'id', s.id, 'kind', s.kind, 'template', s.template, 'language', 'ar', 'is_test', s.is_test,
      'channel_id', s.channel_id, 'from', s.from_address, 'waba_id', s.waba_id, 'sending_enabled', s.sending_enabled, 'to', s.to_phone,
      'handoff', case when s.handoff_id is not null then (
        select jsonb_build_object('token', s.token, 'branch', s.branch_slug, 'both', coalesce(s.both_branches, false), 'summary', s.summary, 'ref', s.ref_text, 'reason', s.reason,
                 'guest_name', coalesce((select nullif(btrim(r.guest_name), '') from public.reservations r where r.phone = g.phone and not r.is_test order by r.created_at desc limit 1),
                                        nullif(btrim(g.wa_profile_name), '')),
                 'guest_phone', g.phone,
                 -- S1c: a social guest has no phone — the alert names the channel instead
                 'channel_kind', (select ch.kind from public.hub_channels ch where ch.id = c.channel_id))
          from public.hub_conversations c join public.guest_profiles g on g.id = c.guest_profile_id where c.id = s.conversation_id) end,
      'report', case when s.kind = 'report' then (select jsonb_build_object('day', d.day, 'data', d.data) from public.hub_daily_reports d where d.day = s.report_day)
                     when s.kind = 'report_test' then jsonb_build_object('day', s.report_day, 'data', s.payload) end);
  end loop;
  return v_out;
end;
$$;

create or replace function internal.hub_conv_edit(p_id uuid) returns public.hub_conversations
language plpgsql security definer set search_path = '' as $$
declare c public.hub_conversations;
begin
  select * into c from public.hub_conversations x where x.id = p_id for update;
  if c.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if not internal.can_conv(c, 'edit') then raise exception 'not allowed' using errcode = '42501'; end if;
  return c;
end;
$$;

create or replace function public.hub_inbox_list(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_tab text := coalesce(nullif(p ->> 'tab', ''), 'waiting');
  v_q text := btrim(coalesce(p ->> 'q', ''));
  v_digits text := regexp_replace(coalesce(p ->> 'q', ''), '[^0-9]', '', 'g');
  v_limit integer := least(greatest(coalesce((p ->> 'limit')::integer, 50), 1), 200);
  v_before timestamptz := nullif(p ->> 'before', '')::timestamptz;
  v_blocked boolean := coalesce((p ->> 'blocked')::boolean, false);
  v_rows jsonb;
  v_counts jsonb;
  v_units jsonb;
begin
  if not internal.can('inbox', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  if v_tab not in ('waiting', 'assistant', 'drafts', 'all', 'closed') then raise exception 'hub_tab' using errcode = '22023'; end if;
  with base as (
    select c.*, u.key as unit_key, coalesce(v.name_ar, u.name_ar) as unit_name, ch.kind as channel_kind, g as gp,
           c.state = 'human' and c.waiting_since is not null as t_waiting,
           c.state not in ('human', 'closed') as t_assistant,
           exists (select 1 from public.hub_messages d where d.conversation_id = c.id and d.status = 'pending_approval') as t_drafts,
           c.state = 'closed' as t_closed,
           greatest(coalesce(c.last_guest_at, c.created_at), coalesce(c.last_staff_at, c.created_at), coalesce(c.last_assistant_at, c.created_at), c.created_at) as last_at
      from public.hub_conversations c
      join public.hub_units u on u.id = c.unit_id
      left join public.dining_venues v on v.id = u.dining_venue_id
      join public.hub_channels ch on ch.id = c.channel_id
      join public.guest_profiles g on g.id = c.guest_profile_id
     where internal.can_conv(c, 'view')
       and (g.hub_blocked_at is not null) = v_blocked
       and (nullif(p ->> 'unit', '') is null or u.id::text = p ->> 'unit' or u.key = p ->> 'unit')
       and (nullif(p ->> 'state', '') is null or c.state = p ->> 'state')
       and (nullif(p ->> 'channel', '') is null or ch.kind = p ->> 'channel')
       and (nullif(p ->> 'language', '') is null or coalesce(c.language, g.language) = p ->> 'language')
       and (nullif(p ->> 'topic', '') is null or (p ->> 'topic') = any (c.topics))
       and (nullif(p ->> 'tag', '') is null or (p ->> 'tag') = any (c.tags))
       and (nullif(p ->> 'owner', '') is null
            or (p ->> 'owner' = 'me' and c.owner_kind = 'staff' and c.owner_staff_id = auth.uid())
            or (p ->> 'owner' = 'none' and c.owner_kind is null)
            or (p ->> 'owner' in ('phone', 'assistant') and c.owner_kind = p ->> 'owner')
            or (c.owner_staff_id::text = p ->> 'owner'))
       and (v_q = ''
            or (v_q ~* '^AR-' and exists (select 1 from public.reservations r where r.profile_id = g.id and r.ref ilike v_q || '%'))
            or (v_q !~* '^AR-' and (coalesce(g.name, '') ilike '%' || v_q || '%' or coalesce(g.wa_profile_name, '') ilike '%' || v_q || '%'
                                    or (char_length(v_digits) >= 3 and coalesce(g.phone, '') like '%' || v_digits || '%'))))
  ),
  counts as (
    select jsonb_build_object('waiting', count(*) filter (where t_waiting), 'assistant', count(*) filter (where t_assistant),
                              'drafts', count(*) filter (where t_drafts), 'all', count(*) filter (where not t_closed), 'closed', count(*) filter (where t_closed)) as j
      from base
  ),
  page as (
    select * from base b
     where ((v_tab = 'waiting' and b.t_waiting) or (v_tab = 'assistant' and b.t_assistant) or (v_tab = 'drafts' and b.t_drafts)
            or (v_tab = 'all' and not b.t_closed) or (v_tab = 'closed' and b.t_closed))
       and (v_before is null or b.last_at < v_before)
     order by b.last_at desc, b.id desc
     limit v_limit + 1
  )
  select (select j from counts),
         coalesce((select jsonb_agg(jsonb_build_object(
           'id', x.id, 'unit_id', x.unit_id, 'unit_key', x.unit_key, 'unit_name', x.unit_name, 'channel_kind', x.channel_kind,
           'state', x.state, 'owner_kind', x.owner_kind, 'owner_staff_id', x.owner_staff_id, 'owner_name', internal.staff_name(x.owner_staff_id),
           'tags', to_jsonb(x.tags), 'topics', to_jsonb(x.topics), 'priority', x.priority, 'language', coalesce(x.language, (x.gp).language),
           'waiting_since', x.waiting_since, 'window_expires_at', x.window_expires_at, 'standby_until', internal.hub_standby_until(x.id), 'is_test', x.is_test, 'blocked', (x.gp).hub_blocked_at is not null,
           'name', internal.hub_guest_label(x.gp), 'phone_last4', right(coalesce((x.gp).phone, ''), 4), 'last_at', x.last_at,
           'unread', (select count(*) from public.hub_messages i where i.conversation_id = x.id and i.direction = 'in'
                        and i.sent_at > coalesce(greatest(x.last_staff_at, x.last_assistant_at), '-infinity'::timestamptz)),
           'last', (select jsonb_build_object('author', l.author, 'kind', l.kind, 'line', left(split_part(coalesce(l.body, ''), chr(10), 1), 120), 'at', l.sent_at)
                      from public.hub_messages l where l.conversation_id = x.id and l.kind <> 'note' order by l.sent_at desc, l.created_at desc limit 1))
           order by x.last_at desc, x.id desc) from page x), '[]'::jsonb)
    into v_counts, v_rows;
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'name', coalesce(v.name_ar, u.name_ar), 'status', u.status) order by u.sort), '[]') into v_units
    from public.hub_units u left join public.dining_venues v on v.id = u.dining_venue_id where internal.can_unit(u.id, 'view')
       or (u.kind = 'brand' and exists (select 1 from public.hub_conversations y where y.unit_id = u.id and internal.can_conv(y, 'view')));
  return jsonb_build_object('rows', case when jsonb_array_length(v_rows) > v_limit then v_rows - v_limit else v_rows end,
                            'more', jsonb_array_length(v_rows) > v_limit, 'counts', v_counts, 'units', v_units, 'timers', internal.hub_timers(),
                            'inbox_on', internal.hub_setting_bool('hub_inbox_on'), 'can_edit', internal.can('inbox', 'edit'));
end;
$$;

create or replace function public.hub_inbox_badge(p_test boolean default false) returns integer
language sql stable security definer set search_path = '' as $$
  select count(*)::integer from public.hub_conversations c join public.guest_profiles g on g.id = c.guest_profile_id
   where c.state = 'human' and c.waiting_since is not null and g.hub_blocked_at is null and (not c.is_test or coalesce(p_test, false))
     and internal.can_conv(c, 'view')
$$;

create or replace function public.hub_guest_conversations(p_profile uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not internal.can('guests', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  return jsonb_build_object(
    'total', (select count(*) from public.hub_conversations c where c.guest_profile_id = p_profile),
    'open', (select count(*) from public.hub_conversations c where c.guest_profile_id = p_profile and c.state <> 'closed'),
    'by_unit', (select coalesce(jsonb_agg(jsonb_build_object('unit_name', x.name, 'count', x.n) order by x.n desc), '[]') from (
                  select coalesce(v.name_ar, u.name_ar) as name, count(*) as n from public.hub_conversations c join public.hub_units u on u.id = c.unit_id
                    left join public.dining_venues v on v.id = u.dining_venue_id where c.guest_profile_id = p_profile group by 1) x),
    'can_open', internal.can('inbox', 'view'),
    'episodes', case when internal.can('inbox', 'view') then (
      select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'unit_name', coalesce(v.name_ar, u.name_ar), 'state', c.state, 'created_at', c.created_at,
                                                   'closed_at', c.closed_at, 'topics', to_jsonb(c.topics),
                                                   'closed_reason', (select e.reason from public.hub_conversation_events e where e.conversation_id = c.id and e.kind = 'close' order by e.at desc limit 1))
                                order by c.created_at desc), '[]')
        from public.hub_conversations c join public.hub_units u on u.id = c.unit_id left join public.dining_venues v on v.id = u.dining_venue_id
       where c.guest_profile_id = p_profile and internal.can_conv(c, 'view')) else '[]'::jsonb end);
end;
$$;

create or replace function public.hub_thread(p_conversation uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  g public.guest_profiles;
  u public.hub_units;
  ch public.hub_channels;
  st jsonb;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null or not internal.can_conv(c, 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  st := internal.hub_assistant_state(u);
  return jsonb_build_object(
    'conversation', jsonb_build_object(
      'id', c.id, 'unit_id', u.id, 'unit_key', u.key, 'unit_kind', u.kind, 'branch', u.branch_slug,
      'unit_name', coalesce((select v.name_ar from public.dining_venues v where v.id = u.dining_venue_id), u.name_ar),
      'channel_kind', ch.kind, 'channel_address', ch.address, 'sending_enabled', ch.sending_enabled,
      'state', c.state, 'state_before_human', c.state_before_human, 'test_state', c.test_state, 'owner_kind', c.owner_kind, 'owner_staff_id', c.owner_staff_id,
      'owner_name', internal.staff_name(c.owner_staff_id), 'human_reason', c.human_reason, 'priority', c.priority,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'waiting_since', c.waiting_since,
      -- S1: the conversation's branch on «السوشيال», and staff text with «Human Agent» (7 days) once Meta approved it
      'branch_named', c.branch_slug, 'channel_provider', ch.provider,
      'human_agent_until', case when ch.provider = 'meta' and (select x.meta_human_agent from public.hub_units x where x.id = ch.unit_id) then c.last_guest_at + interval '7 days' end,
      'last_guest_at', c.last_guest_at, 'last_staff_at', c.last_staff_at, 'tags', to_jsonb(c.tags), 'topics', to_jsonb(c.topics),
      'referral', c.referral, 'created_at', c.created_at, 'closed_at', c.closed_at, 'is_test', c.is_test,
      'can_edit', internal.can_conv(c, 'edit'),
      'unit_mode', u.assistant_mode,
      'assistant', jsonb_build_object('active', (st ->> 'active')::boolean, 'mode', st ->> 'mode', 'reason', st ->> 'reason'),
      'can_release', internal.can_conv(c, 'edit') and c.state = 'human' and (st ->> 'active')::boolean and st ->> 'mode' in ('shadow', 'licensed'),
      'can_pause', internal.can_unit(c.unit_id, 'edit') and u.assistant_mode <> 'off',
      -- «وضع الاستعداد»: the countdown «المساعد يرد بعد m:ss»
      'standby_until', internal.hub_standby_until(c.id),
      -- H9 fix 3: why the last turn waited or not («ينتظر رد الفريق» / «لم ينتظر: …»)
      'standby_last', internal.hub_standby_last(c.id),
      'templates_approved', (select coalesce(jsonb_agg(t.language order by t.language), '[]') from public.hub_templates t
                              where t.channel_id = c.channel_id and t.name = 'hub_reply_ready' and t.status = 'APPROVED')),
    'guest', jsonb_build_object(
      'id', g.id, 'name', g.name, 'wa_name', g.wa_profile_name, 'label', internal.hub_guest_label(g), 'phone', g.phone, 'language', g.language,
      'member', g.club_joined_at is not null, 'consent', g.consent, 'opted_out', g.wa_opt_out_at is not null, 'blocked', g.hub_blocked_at is not null,
      'marketing_hold', g.marketing_hold_at is not null, 'tags', to_jsonb(g.tags), 'notes', g.notes,
      'stays', (select count(*) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'last_stay', (select max(r.check_out) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'bookings', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out)
                                             order by r.check_in desc), '[]')
                     from (select * from public.reservations r where r.profile_id = g.id and internal.can_branch(r.branch) order by r.check_in desc limit 10) r)),
    'messages', (select coalesce(jsonb_agg(jsonb_build_object(
                   'id', m.id, 'direction', m.direction, 'author', m.author, 'staff_id', m.staff_id, 'staff_name', internal.staff_name(m.staff_id),
                   'kind', m.kind, 'body', m.body, 'payload', m.payload, 'language', m.language, 'media_path', m.media_path, 'media_mime', m.media_mime,
                   -- H7: «تفريغ صوتي» and the image's category
                   'transcript', m.transcript, 'transcript_seconds', m.transcript_seconds, 'media_category', m.media_category, 'media_status', m.media_status,
                   'media_purged', m.media_purged_at is not null or m.media_pending_delete, 'status', m.status, 'error_code', m.error_code,
                   'sent_at', m.sent_at, 'purged', m.purged_at is not null, 'unanswered', exists (select 1 from public.hub_unanswered q where q.message_id = m.id),
                   'translation', m.translation_ar, 'approved_by_name', internal.staff_name(m.approved_by), 'approved_at', m.approved_at,
                   'edited_before_send', m.edited_before_send, 'turn_id', m.turn_id,
                   'sources', (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'key', k.key, 'title', coalesce(k.live ->> 'title_ar', k.title_ar)) order by k.key), '[]')
                                 from public.hub_knowledge_cards k where k.id = any (m.source_card_ids)))
                   order by m.sent_at, m.created_at), '[]') from public.hub_messages m where m.conversation_id = c.id),
    'templates', (select coalesce(jsonb_agg(t order by t ->> 'at'), '[]') from (
                    select jsonb_build_object('source', 'booking', 'template', w.template, 'meta_template', w.meta_template, 'status', w.status, 'ref', w.ref,
                                              'branch', w.branch, 'language', w.language, 'at', w.created_at) t
                      from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                     where r.profile_id = g.id and internal.can_branch(r.branch) and w.status not in ('skipped')
                    union all
                    select jsonb_build_object('source', 'eyab', 'template', e.template, 'status', e.status, 'branch', e.branch, 'language', e.language, 'at', e.created_at)
                      from public.eyab_messages e where e.profile_id = g.id and e.status not in ('skipped') and internal.can_branch(e.branch)) s),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'from', e.from_value, 'to', e.to_value, 'reason', e.reason, 'at', e.at,
                                                           'actor', internal.staff_name(e.actor_staff_id)) order by e.at, e.id), '[]')
                 from public.hub_conversation_events e where e.conversation_id = c.id),
    'episodes', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'unit_name', xu.name_ar, 'state', x.state, 'created_at', x.created_at, 'closed_at', x.closed_at)
                                           order by x.created_at desc), '[]')
                   from public.hub_conversations x join public.hub_units xu on xu.id = x.unit_id
                  where x.guest_profile_id = g.id and x.id <> c.id and internal.can_conv(x, 'view')),
    'transfer_units', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', coalesce(v.name_ar, t.name_ar)) order by t.sort), '[]')
                         from public.hub_units t left join public.dining_venues v on v.id = t.dining_venue_id where t.status = 'active' and t.id <> u.id),
    'team', (select coalesce(jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name) order by s.full_name), '[]')
               from public.hub_unit_members m join public.staff s on s.user_id = m.staff_id
               join public.staff_permissions sp on sp.user_id = s.user_id and sp.section = 'inbox' and sp.level >= 'edit'
              where m.unit_id = u.id and s.active),
    'timers', internal.hub_timers());
end;
$$;

create or replace function public.hub_alert_open(p_token text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare h public.hub_handoffs;
begin
  if coalesce(p_token, '') !~ '^[0-9a-f]{32}$' then return jsonb_build_object('allowed', false, 'reason', 'invalid'); end if;
  select * into h from public.hub_handoffs where token = p_token;
  if h.id is null then return jsonb_build_object('allowed', false, 'reason', 'not_found'); end if;
  if not internal.can_conv_id(h.conversation_id, 'view') then return jsonb_build_object('allowed', false, 'reason', 'forbidden'); end if;
  if h.opened_at is null then
    update public.hub_handoffs set opened_at = now(), opened_by = auth.uid(), opened_via = 'link' where id = h.id;
  end if;
  return jsonb_build_object('allowed', true, 'conversation_id', h.conversation_id);
end;
$$;

create or replace function public.hub_handoff_seen(p_conversation uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare c public.hub_conversations;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null or c.handoff_id is null or not internal.can_conv(c, 'view') then return; end if;
  update public.hub_handoffs set opened_at = now(), opened_by = auth.uid(), opened_via = 'inbox' where id = c.handoff_id and opened_at is null;
end;
$$;

-- the bathroom amenities card (Ahmed, 25 Nov 2026), both branches and «السوشيال» — published at once like H11's cards
insert into public.hub_knowledge_cards (key, unit_keys, topic_keys, title_ar, title_en, text_ar, text_en, source, source_date, verified_at, status, sort, card_kind)
select 'k-room-bath-amenities', '{airport-road,shafa-road,social}', '{room_amenities}', 'مستلزمات الحمام في الغرف', 'Bathroom amenities in the rooms',
       'تتوفر في جميع الغرف مستلزمات الحمام: شامبو، وبلسم، وجل استحمام، وصابون.', 'All rooms have bathroom amenities: shampoo, conditioner, shower gel and soap.', 'Ahmed, 25 Nov 2026', '2026-11-25', now(), 'draft', 913, 'fact'
 where not exists (select 1 from public.hub_knowledge_cards k where k.text_ar like '%شامبو%' or k.text_en ilike '%shampoo%')
on conflict (key) do nothing;
update public.hub_knowledge_cards k set live = internal.hub_card_snapshot(k), status = 'published', published_at = now(), first_published_at = coalesce(k.first_published_at, now())
 where k.key = 'k-room-bath-amenities' and k.live is null and k.status = 'draft';

-- the two lab items of the card («عندكوا شامبو؟» and its English twin)
do $$
declare v_sort integer := coalesce((select max(sort) from public.hub_test_items), 0) + 1;
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($s2a$[{"key":"s2-01","unit":"social","language":"ar","messages":["عندكوا شامبو؟"],"expect":{"action":"conversation","steps":[{"outcome":"reply","must_include":["شامبو"],"must_not_include":["سيكمل معك"]}]},"note":"the bathroom amenities card (Ahmed, 25 Nov 2026) — on 25 Nov 21:55 this question had no card and went to the team","tags":["conversation","social","room_amenities"],"context":{}},{"key":"s2-02","unit":"social","language":"en","messages":["Do you have shampoo in the rooms?"],"expect":{"action":"conversation","steps":[{"outcome":"reply","must_include":["shampoo"],"must_not_include":["will continue with you"]}]},"note":"the bathroom amenities card in English","tags":["conversation","social","room_amenities"],"context":{}}]$s2a$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end $$;
